/* Signature Somali Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ahmednur": "From Ahmed + nur (light): 'praised light'.", "Fatimahodan": "From Fatima + Hodan.", "Hassangure": "From Hassan + gure (good fortune?).", "Aminawarsame": "From Amina + Warsame (good news).", "Abdifatah": "From Abdi + fatah (victory): 'servant of victory'.", "Hodanbilan": "From Hodan + bilan (prosperity?).", "Ahmednurawi": "Signature clan-style surname: 'of Ahmednur'.", "Fatimahodanle": "Signature clan-style surname.", "Hassangureed": "Signature clan-style surname.", "Abdifatahle": "Signature clan-style surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ahmednur';
console.log(lookup(q));

